"""Optional PDF export of a plan already generated by Studio."""
from __future__ import annotations
from pathlib import Path
from collections import Counter, defaultdict
from xml.sax.saxutils import escape
from reportlab.lib import colors
from reportlab.lib.pagesizes import A4
from reportlab.lib.styles import ParagraphStyle
from reportlab.pdfbase import pdfmetrics
from reportlab.pdfbase.ttfonts import TTFont
from reportlab.platypus import BaseDocTemplate, Frame, PageTemplate, Paragraph, Spacer, Table, TableStyle
from xml.sax.saxutils import escape


FONT_PATHS = [Path("/Library/Fonts/Arial Unicode.ttf"), Path("/System/Library/Fonts/Supplemental/Arial Unicode.ttf")]
FONT = "PlanUnicode"
LABELS = {
    "generated_video": "Створене відео",
    "stock_video": "Стокове відео",
    "generated_photo": "Створене фото",
    "stock_photo": "Стокове фото",
    "animation": "Анімація / схема",
    "razgon_2d": "2D-анімація Razgon",
    "text": "Текстова сцена",
    "host": "Ведучий",
}
PALETTE = {
    "generated_video": colors.HexColor("#1A73E8"),
    "stock_video": colors.HexColor("#18A0A6"),
    "generated_photo": colors.HexColor("#9B59B6"),
    "stock_photo": colors.HexColor("#70A44B"),
    "animation": colors.HexColor("#EA8C27"),
    "razgon_2d": colors.HexColor("#D946EF"),
    "text": colors.HexColor("#D95771"),
    "host": colors.HexColor("#475569"),
}


def clock(seconds: float) -> str:
    seconds = int(round(seconds))
    return f"{seconds // 60:02d}:{seconds % 60:02d}"


def p(text: str, style: ParagraphStyle) -> Paragraph:
    return Paragraph(escape(text).replace("\n", "<br/>"), style)


def draw_page(canvas, doc):
    canvas.saveState()
    width, _ = A4
    canvas.setStrokeColor(colors.HexColor("#CBD5E1"))
    canvas.line(36, 34, width - 36, 34)
    canvas.setFont(FONT, 8)
    canvas.setFillColor(colors.HexColor("#64748B"))
    canvas.drawString(36, 22, "Попередній план для затвердження")
    canvas.drawRightString(width - 36, 22, str(doc.page))
    canvas.restoreState()


def build_pdf(output: Path, channel: str, groups: list[list[str]], times: list[tuple[float, float]], formats: list[str], config: dict, measured: bool) -> dict:
    if not groups:
        raise ValueError("Сценарій порожній")
    font_file = next((path for path in FONT_PATHS if path.is_file()), None)
    if font_file is None:
        raise RuntimeError("Потрібен шрифт Arial Unicode для українського PDF")
    if FONT not in pdfmetrics.getRegisteredFontNames():
        pdfmetrics.registerFont(TTFont(FONT, str(font_file)))
    output.parent.mkdir(parents=True, exist_ok=True)
    regular = ParagraphStyle("regular", fontName=FONT, fontSize=8.7, leading=12.5, textColor=colors.HexColor("#263445"))
    small = ParagraphStyle("small", parent=regular, fontSize=7.5, leading=10.8)
    title = ParagraphStyle("title", parent=regular, fontSize=17, leading=21, textColor=colors.HexColor("#17283B"), spaceAfter=9)
    subtitle = ParagraphStyle("subtitle", parent=regular, fontSize=11, leading=15, spaceBefore=10, spaceAfter=6)
    head = ParagraphStyle("head", parent=small, fontSize=8, textColor=colors.white)
    total = times[-1][1]
    seconds = defaultdict(float)
    counts = Counter(formats)
    for (start, end), fmt in zip(times, formats):
        seconds[fmt] += end - start
    story = [p(f"Візуальний план: {channel}", title)]
    timing_label = "час за готовою озвучкою" if measured else "орієнтовний час"
    story.append(p(f"Тривалість {clock(total)}  |  Кадрів {len(groups)}  |  Таймінг: {timing_label}", regular))
    story.append(p("Частки основних форматів", subtitle))
    summary = [[p("Формат", head), p("Кадрів", head), p("Час", head), p("Частка часу", head)]]
    for fmt in LABELS:
        if not counts[fmt]:
            continue
        summary.append([p(LABELS[fmt], regular), str(counts[fmt]), clock(seconds[fmt]), f"{seconds[fmt] / total * 100:.1f}%"])
    summary.append([p("Разом", regular), str(len(groups)), clock(total), "100%"])
    table = Table(summary, colWidths=[245, 68, 78, 86], repeatRows=1)
    table.setStyle(TableStyle([
        ("BACKGROUND", (0, 0), (-1, 0), colors.HexColor("#233C5B")),
        ("GRID", (0, 0), (-1, -1), .3, colors.HexColor("#D7E0E9")),
        ("VALIGN", (0, 0), (-1, -1), "MIDDLE"),
        ("ROWBACKGROUNDS", (0, 1), (-1, -2), [colors.white, colors.HexColor("#F4F7FA")]),
        ("BACKGROUND", (0, -1), (-1, -1), colors.HexColor("#E6EDF4")),
        ("LEFTPADDING", (0, 0), (-1, -1), 7),
        ("TOPPADDING", (0, 0), (-1, -1), 6),
        ("BOTTOMPADDING", (0, 0), (-1, -1), 6),
    ]))
    story.extend([table, Spacer(1, 5)])
    story.append(p("Таймлайн кадрів", subtitle))
    story.append(p("Формат і розташування визначені автоматично. Конкретний кліп, фото, композицію та напис уточнюємо під зміст репліки після затвердження плану.", small))
    rows = [[p("№ / час", head), p("Репліка", head), p("Запланований формат", head)]]
    for index, (group, (start, end), fmt) in enumerate(zip(groups, times, formats), 1):
        rows.append([
            p(f"{index:03d}\n{clock(start)} - {clock(end)}", small),
            p(" ".join(group), small),
            p(LABELS[fmt], small),
        ])
    timeline = Table(rows, colWidths=[75, 283, 119], repeatRows=1, hAlign="LEFT")
    timeline_style = [
        ("BACKGROUND", (0, 0), (-1, 0), colors.HexColor("#233C5B")),
        ("GRID", (0, 0), (-1, -1), .25, colors.HexColor("#D7E0E9")),
        ("VALIGN", (0, 0), (-1, -1), "TOP"),
        ("TOPPADDING", (0, 0), (-1, -1), 6),
        ("BOTTOMPADDING", (0, 0), (-1, -1), 6),
        ("LEFTPADDING", (0, 0), (-1, -1), 6),
    ]
    for i, fmt in enumerate(formats, 1):
        timeline_style.append(("BACKGROUND", (2, i), (2, i), colors.Color(*PALETTE[fmt].rgb(), alpha=.14)))
    timeline.setStyle(TableStyle(timeline_style))
    story.append(timeline)
    doc = BaseDocTemplate(str(output), pagesize=A4, leftMargin=36, rightMargin=36, topMargin=35, bottomMargin=45)
    frame = Frame(doc.leftMargin, doc.bottomMargin, doc.width, doc.height, id="normal", leftPadding=0, rightPadding=0, topPadding=0, bottomPadding=0)
    doc.addPageTemplates(PageTemplate(id="plan", frames=[frame], onPage=draw_page))
    doc.build(story)
    return {"channel": channel, "frames": len(groups), "duration_seconds": round(total, 2), "format_seconds": {key: round(value, 2) for key, value in seconds.items()}, "timing": timing_label, "pdf": str(output)}


